import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
from collections import Counter

BASE = 'http://localhost:8080'
token = None

def get(path, authenticated=True):
    global token
    for attempt in range(30):
        if authenticated and token is None:
            token = get('/token', False)['token']
        headers = {'Authorization': 'Bearer ' + token} if authenticated else {}
        req = urllib.request.Request(BASE + path, headers=headers, method='POST' if path == '/token' else 'GET')
        try:
            with urllib.request.urlopen(req, timeout=30) as response:
                return json.load(response)
        except urllib.error.HTTPError as error:
            if error.code == 401 and authenticated:
                token = None
                continue
            if error.code == 429:
                wait = error.headers.get('Retry-After')
                if wait is None:
                    try:
                        body = json.loads(error.read())
                        wait = body.get('retry_after', body.get('retry_after_seconds', 1))
                    except Exception:
                        wait = 1
                delay = float(wait)
                print(f'Rate limited on {path}; sleeping {delay}s', flush=True)
                time.sleep(delay)
                continue
            if error.code >= 500:
                print(f'HTTP {error.code} on {path}; retrying', flush=True)
                time.sleep(min(attempt + 1, 10))
                continue
            raise
        except (TimeoutError, urllib.error.URLError) as error:
            print(f'Request error on {path}: {error}; retrying', flush=True)
            time.sleep(min(attempt + 1, 10))
    raise RuntimeError(f'Retries exhausted for {path}')

orders = {}
duplicates = 0
page_num = 1
while True:
    data = get(f'/orders?page={page_num}')
    assert data['page'] == page_num
    for order in data['items']:
        old = orders.get(order['id'])
        if old is not None:
            assert old == order, f\"Conflicting duplicate {order['id']}\"
            duplicates += 1
        else:
            orders[order['id']] = order
    print(f\"Page {page_num}/{data['total_pages']}: {len(data['items'])} listings, {len(orders)} unique, {duplicates} repeats\", flush=True)
    if data['next'] is None:
        assert page_num == data['total_pages']
        break
    assert data['next'] == f'/orders?page={page_num + 1}'
    page_num += 1

start = datetime(2025,3,1,tzinfo=timezone.utc)
end = datetime(2025,6,1,tzinfo=timezone.utc)
qualifying = []
for order in orders.values():
    if order['status'] "'!= '"'shipped':
        continue
    placed = datetime.fromisoformat(order['placed_at'].replace('Z','+00:00')).astimezone(timezone.utc)
    if start <= placed < end:
        qualifying.append(order)

customers = {}
for i, customer_id in enumerate(sorted({o['customer_id'] for o in qualifying}), 1):
    customer = get(f'/customers/{customer_id}')
    assert customer['id'] == customer_id
    assert customer['region'] in ('north','south','east','west')
    assert isinstance(customer['discount_pct'], int)
    customers[customer_id] = customer
    if i % 20 == 0:
        print(f'Customers: {i}/{len({o[\"customer_id\"] for o in qualifying})}', flush=True)

by_region = {r:0 for r in ('north','south','east','west')}
for order in qualifying:
    customer = customers[order['customer_id']]
    net = (Decimal(order['amount_cents']) * (Decimal(100)-Decimal(customer['discount_pct'])) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
    by_region[customer['region']] += int(net)
result = {'total_cents':sum(by_region.values()), 'order_count':len(qualifying), 'duplicates_skipped':duplicates, 'by_region':by_region}
assert len(qualifying) == len({o['id'] for o in qualifying})
assert result['total_cents'] == sum(result['by_region'].values())
with open('/workspace/result.json','w') as f:
    json.dump(result,f,indent=2)
    f.write('\\n')
print('RESULT',json.dumps(result),flush=True)
print('STATUS',dict(Counter(o['status'] for o in orders.values())),flush=True)
